coding.solution:
public class PasswordPolicy {
    public static boolean isValid(String p) {
        if (p == null || p.length() < 8 || p.length() > 64) {
            return false;
        }
        boolean digit = p.chars().anyMatch(Character::isDigit);
        boolean upper = p.chars().anyMatch(Character::isUpperCase);
        return digit && upper;
    }
}

coding.junit:
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.CsvSource;

class PasswordPolicyTest {
    @ParameterizedTest(name = "{0} -> {1}")
    @CsvSource({
        "Abcdef1, false",
        "Abcdefg1, true",
        "abcdefg1, false",
        "Abcdefgh, false"
    })
    void checksRules(String password, boolean expected) {
        assertEquals(expected, PasswordPolicy.isValid(password));
    }

    @Test
    void upperLengthBoundary() {
        String sixtyFour = "A1" + "x".repeat(62);
        assertEquals(true, PasswordPolicy.isValid(sixtyFour));
        assertEquals(false, PasswordPolicy.isValid(sixtyFour + "x"));
    }

    @Test
    void nullIsInvalid() {
        assertFalse(PasswordPolicy.isValid(null));
    }
}

