import static org.junit.jupiter.api.Assertions.assertDoesNotThrow;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;

import org.junit.jupiter.api.Test;
import org.opentest4j.MultipleFailuresError;

class UserAssertionsTest {
    @Test
    void passesForActiveAdmin() {
        assertDoesNotThrow(() -> UserAssertions.assertActiveAdmin(new User("ana@example.com", "admin", true)));
    }

    @Test
    void reportsAllFailuresTogether() {
        MultipleFailuresError e = assertThrows(MultipleFailuresError.class,
            () -> UserAssertions.assertActiveAdmin(new User("bo@other.org", "viewer", false)));
        assertEquals(3, e.getFailures().size());
    }
}
